<script setup lang="ts">import { nextTick, ref, watch } from 'vue'; import type { ChronicleEvent, Tournament } from '../types'; const props = defineProps<{ open: boolean; events: ChronicleEvent[]; tournament: Tournament | null }>(); const emit = defineEmits<{ close: [] }>(); const button = ref<HTMLButtonElement>(); const rankName = (n: number) => ['零','一','二','三','四','五','六','七','八','九','十'][Math.min(n,10)] || n; watch(() => props.open, open => { if (open) nextTick(() => { (document.activeElement as HTMLElement)?.blur(); button.value?.focus() }) })</script>
<template><Transition name="fade"><div v-if="open" class="modal-overlay z-[150]"><div class="event-dialog"><template v-if="tournament"><div class="event-title">🏆 年 终 论 剑</div><div class="my-2 text-center text-3xl text-gold">第 {{ rankName(tournament.rank) }} 名</div><div class="mb-3 text-center text-sm text-ink-light">天下共 <strong>{{ tournament.total_sects }}</strong> 派与会 · 战力：{{ tournament.power }}<br>{{ tournament.desc_text }}</div><hr v-if="events.length" class="my-2 border-dashed border-border"></template><template v-if="events.length"><div class="event-title">📜 本月纪事</div><div v-for="(event, i) in events" :key="i" class="event-item" :class="event.mood">{{ event.text }}</div></template><button ref="button" class="btn btn-primary event-dismiss" @click="emit('close')">知道了</button></div></div></Transition></template>

